#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m;
    cin >> n >> m;
    vector<int> a(n);
    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<int> sub_sums;
    int best_result = 0;
    int limit1 = 1 << ((n / 2) + (n % 2));
    for (int subset_mask = 0; subset_mask < limit1; ++subset_mask) {
        int sum_part = 0;
        int current_mask = subset_mask;
        for (int _ = 0; _ < 20; ++_) {
            if (current_mask & 1) {
                sum_part += a[_];
            }
            current_mask >>= 1;
        }
        sub_sums.push_back(sum_part % m);
    }
    std::sort(sub_sums.begin(), sub_sums.end());

    int limit2 = 1 << (n / 2);
    for (int second_mask = 0; second_mask < limit2; ++second_mask) {
        int sum_second = 0;
        int mask_copy = second_mask;
        for (int j = 0; j < 20; ++j) {
            if (mask_copy & 1) {
                sum_second += a[(n / 2) + (n % 2) + j];
            }
            mask_copy >>= 1;
        }
        sum_second %= m;

        int idx = (int)(std::lower_bound(sub_sums.begin(), sub_sums.end(), m - sum_second - 1) - sub_sums.begin());
        int candidate;
        if (idx < (int)sub_sums.size()) {
            candidate = sub_sums[idx];
            if (candidate > m - sum_second - 1 && idx - 1 >= 0) {
                candidate = sub_sums[idx - 1];
            }
        } else {
            candidate = sub_sums.back();
        }
        best_result = max({best_result, (sum_second + candidate) % m, (sum_second + sub_sums.back()) % m});
    }
    cout << best_result << "\n";
    return 0;
}
